  if (auto != null) return { mode: "auto", html: readonlyBox(auto + "٪ — تُحسب تلقائيًا" + (fid === "attendanceRate" ? " (الحاضرات ÷ المسجلات)" : " (المستمرات ÷ المشاركات عند البداية)")) };
