    if (j < 0 || after.slice(0, j).some((x) => !x.allowSkip)) return "ما يمديك ترسله لهذه المرحلة — اللي بينكم لازم يمر عليها.";
    log.push(apLogEntry("skip", cur.key, after[j].key, "تجاوزت " + cur.name + ": " + after.slice(0, j).map((x) => x.name).join("، ")));
