    const bs = (cfg.badges || []).map((id) => { const v = txt(x, id); if (!v) return ""; if (rows.length > 1 && rows.every((r) => txt(r, id) === v)) return ""; return badge(id, v); }).join("") + routeBadgeHtml(sid, x);
    const t = txt(x, cfg.title);
