  let ind = ""; try { const its = indicatorBoardItems(entries, (entries || []).length > 1); ind = its.length ? `<div class="rpt-stat-grp">مؤشرات الأداء</div>` + priorityMatrixHtml(its) : ""; } catch (e) {}
