  const views = [["report", "حسب شكل القسم"], ["kpi", "أرقام كبيرة"], ["seq", "متتابعة"], ["two", "عمودان"], ["table", "جدول واحد"]];
  const shapes = Object.entries(SHAPES_LIB).filter(([, v]) => !v.live && v.cat !== "photo");
