  if (notes.length) h += `<div style="font-size:11.5px;font-weight:700;margin:10px 0 3px;">من ملاحظات المستجيبات</div><div style="font-size:11.5px;line-height:1.9;">${notes.slice(0, 3).map((n) => "«" + esc(n) + "»").join(" · ")}</div>`;
