const SHP_CATS = [["text", "نصوص"], ["photo", "صور"], ["stats", "أرقام وإحصاءات"], ["list", "قوائم"], ["time", "خطوط زمنية"], ["flow", "مخططات انسيابية"], ["table", "جداول"]];
