  let h = `<div class="rpt-pc-row"><span>${esc(t.name || t.toolType || "أداة")}</span><b>${rr != null && rr !== "" ? "استجابة " + esc(String(rr)) + "٪" : esc(t.resultQuality || "")}</b></div>`;
